styles:
.b-cta {
    --cta-ring: var(--site-color-accent);
    container-type: inline-size;
    padding-block: var(--site-section-space, var(--site-space-5));
}

.b-cta__inner {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    /* Text → buttons when they stand one under the other; beside each other the column gap. */
    gap: var(--site-section-actions-space, var(--site-space-5)) var(--site-space-5);
    padding: var(--site-space-6) var(--site-space-5);
    border-radius: var(--site-radius-lg);
}

.b-cta--accent {
    --cta-ring: var(--site-color-accent-contrast);
}

.b-cta--accent .b-cta__inner {
    background: var(--site-color-accent);
    color: var(--site-color-accent-contrast);
}

.b-cta--surface .b-cta__inner {
    background: var(--site-color-surface-muted);
    color: var(--site-color-text);
}

.b-cta--plain .b-cta__inner {
    border: 1px solid var(--site-color-border);
    background: var(--site-color-bg);
    color: var(--site-color-text);
}

.b-cta__words {
    min-width: 0;
}

.b-cta__heading {
    margin: 0;
    color: inherit;
    font-size: var(--site-section-title-size, var(--site-font-size-3));
    hyphens: auto;
}

/* The section's H2 type (THEMES §7.2): unset, the prose's own, and only where the prose applies
   (in the main column and under site-prose), so that nothing changes until a site sets it. */
.b-cta__heading:where(.site-main *, .site-prose *) {
    font-family: var(--site-section-title-font, var(--site-font-heading));
    font-size: var(--site-section-title-size, var(--site-font-size-3));
    line-height: var(--site-section-title-line-height, 1.2);
    /* Unset, nothing: an inherited property falls back to the parent's. */
    text-transform: var(--site-section-title-case);
}

.b-cta__text {
    max-width: 40em;
    margin: var(--site-section-title-space, var(--site-space-2)) 0 0;
}

.b-cta--surface .b-cta__text,
.b-cta--plain .b-cta__text {
    color: var(--site-color-text-muted);
}

.b-cta__actions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--site-space-3);
}

.b-cta--accent .b-cta__button:not(.b-cta__button--quiet) {
    background: var(--site-color-accent-contrast);
    color: var(--site-color-accent);
}

.b-cta__button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 44px;
    padding: 0 var(--site-space-5);
    border: 1px solid transparent;
    border-radius: var(--site-radius-md);
    background: var(--site-color-accent);
    color: var(--site-color-accent-contrast);
    font-weight: 600;
    line-height: 1.2;
    text-align: center;
    text-decoration: none;
    transition: background-color var(--site-duration) var(--site-easing), color var(--site-duration) var(--site-easing);
}

.b-cta__button:hover {
    background: color-mix(in srgb, var(--site-color-accent) 85%, var(--site-color-text));
}

.b-cta__button:focus-visible {
    outline: 2px solid var(--cta-ring);
    outline-offset: 2px;
}

.b-cta__button--quiet,
.b-cta__button--quiet:hover {
    border-color: currentColor;
    background: transparent;
    color: inherit;
}

@container (min-width: 44rem) {
    .b-cta__inner {
        flex-direction: row;
        align-items: center;
        justify-content: space-between;
        padding: var(--site-space-6) var(--site-space-7);
    }

    .b-cta__actions {
        flex-shrink: 0;
    }
}

/* The accented words of the heading (==words==) cannot take the accent colour on the accent or over a photo: they keep the colour and lean instead. */
.b-cta--accent .site-accent {
    color: inherit;
    font-style: italic;
}

.b-cta__eyebrow {
    margin: 0 0 var(--site-eyebrow-space, var(--site-space-2));
    /* Unset, the parent's: font-family and line-height are inherited. */
    font-family: var(--site-eyebrow-font);
    font-size: var(--site-eyebrow-size, var(--site-font-size-6));
    font-weight: var(--site-eyebrow-weight, 600);
    line-height: var(--site-eyebrow-line-height);
    letter-spacing: var(--site-eyebrow-letter-spacing, 0.08em);
    text-transform: var(--site-eyebrow-case, uppercase);
}

/* Edge to edge: the band spans the window, its words keep to the column of the page. */
.b-cta.site-bleed {
    padding-block: 0;
}

.b-cta.site-bleed .b-cta__inner {
    padding-inline: max(var(--site-section-gutter, var(--site-gutter)), (100% - var(--site-container-width)) / 2 + var(--site-section-gutter, var(--site-gutter)));
    border-radius: 0;
}

.b-cta--plain.site-bleed .b-cta__inner {
    border-inline: 0;
}

/* On a photo, the shade and the words are two token colours turned round, as in text-tiles:
   dark — a shade of the text colour under words in the page's colour, light — a veil of the
   page's colour under words in the text colour. The dark scheme turns both round together. Even,
   not a gradient: 72% of the text colour over a white pixel still leaves the words 4.5:1 and more
   (WCAG AA). Without a photo the band is the colour of the shade. */
.b-cta--image {
    --cta-shade: var(--site-color-text);
    --cta-ink: var(--site-color-bg);
    --cta-veil: 72%;
    --cta-ring: var(--cta-ink);
}

.b-cta--image.b-cta--light {
    --cta-shade: var(--site-color-bg);
    --cta-ink: var(--site-color-text);
    --cta-veil: 78%;
}

.b-cta--image .b-cta__inner {
    position: relative;
    isolation: isolate;
    overflow: hidden;
    justify-content: flex-end;
    padding-block: var(--cta-space, var(--site-space-8));
    background: var(--cta-shade);
    color: var(--cta-ink);
}

.b-cta__picture {
    position: absolute;
    inset: 0;
    z-index: -2;
    width: 100%;
    max-width: none;
    height: 100%;
    border-radius: 0;
    object-fit: cover;
}

.b-cta__shade {
    position: absolute;
    inset: 0;
    z-index: -1;
    background: color-mix(in srgb, var(--cta-shade) var(--cta-veil), transparent);
}

.b-cta--image .site-accent {
    color: inherit;
    font-style: italic;
}

/* Height: by the words (auto), the screen, or a proportion of the width. A least height, not a
   fixed one: words that need more make the band taller rather than spill out of it. Not
   `aspect-ratio`: on a box that crops its picture (`overflow: hidden`) it is a fixed height, and
   the band is as wide as its container — the block itself. */
.b-cta--screen .b-cta__inner {
    min-height: 100vh;
    min-height: 100svh;
}

.b-cta--ratio-21-9 .b-cta__inner {
    min-height: calc(100cqi * 9 / 21);
}

.b-cta--ratio-16-9 .b-cta__inner {
    min-height: calc(100cqi * 9 / 16);
}

.b-cta--ratio-3-2 .b-cta__inner {
    min-height: calc(100cqi * 2 / 3);
}

.b-cta--ratio-4-3 .b-cta__inner {
    min-height: calc(100cqi * 3 / 4);
}

/* The photo alone: no padding around it, and by the words — there are none — it is as tall as
   the photo itself. */
.b-cta.b-cta--bare .b-cta__inner {
    display: block;
    padding: 0;
}

.b-cta--bare:not(.b-cta--screen, .b-cta--ratio) .b-cta__picture {
    position: relative;
    z-index: auto;
    display: block;
    height: auto;
}

@container (min-width: 44rem) {
    .b-cta--image .b-cta__inner {
        align-items: flex-end;
        justify-content: space-between;
    }
}

/* The gradients (THEMES §9.11): instead of the even shade, the shade's colour fading out — from the
   start side (`gradient-start`: dark at the words, the picture clear at the other end) or from the
   top (`gradient-top`: the page's colour solid down to `--cta-gradient-hold`, then the sketch
   clear). The dark scheme turns them round with the shade. On a narrow band the words run the
   whole width, so the start gradient does not fade out entirely there. */
.b-cta--image.b-cta--gradient-top {
    --cta-shade: var(--site-color-bg);
    --cta-ink: var(--site-color-text);
}

.b-cta--gradient-start .b-cta__shade {
    background: linear-gradient(to right, color-mix(in srgb, var(--cta-shade) var(--cta-gradient-from, 85%), transparent) var(--cta-gradient-hold, 0%), var(--cta-gradient-to, color-mix(in srgb, var(--cta-shade) 55%, transparent)));
}

.b-cta--gradient-top .b-cta__shade {
    background: linear-gradient(to bottom, var(--cta-shade) var(--cta-gradient-hold, 38%), var(--cta-gradient-to, transparent));
}

/* The front picture (`foreground`): over the shade and under nothing, so it is never darkened —
   a brochure or a phone in a PNG or WebP with transparency. Its corner mask is the block's
   `--cta-foreground-radius` (one corner: `0 0 0 3rem`), its size `--cta-foreground-height`. */
.b-cta__foreground {
    display: block;
    align-self: center;
    width: auto;
    max-width: 100%;
    height: auto;
    max-height: var(--cta-foreground-height, 20rem);
    border-radius: var(--cta-foreground-radius, var(--site-radius-lg));
    object-fit: contain;
}

/* Split (`layout: split`): the words on the start side in the middle of the band's height, the
   front picture beside them. Narrow: the words, the picture under them, the button across. */
.b-cta--image.b-cta--split .b-cta__inner {
    justify-content: center;
}

.b-cta--split .b-cta__actions {
    align-self: stretch;
}

.b-cta--split .b-cta__button {
    flex: 1 1 100%;
}

/* At the top in the middle (`layout: top-center`): the words in a column of
   `--cta-column-width` at `--cta-top-space` from the top, the buttons under them, the front
   picture last. */
.b-cta--image.b-cta--top-center .b-cta__inner {
    align-items: center;
    justify-content: flex-start;
    padding-block-start: var(--cta-top-space, var(--site-space-8));
    text-align: center;
}

.b-cta--top-center .b-cta__words {
    max-width: var(--cta-column-width, 46.75rem);
}

.b-cta--top-center .b-cta__text {
    margin-inline: auto;
}

.b-cta--top-center .b-cta__actions {
    justify-content: center;
}

.b-cta--top-center .b-cta__foreground {
    order: 1;
}

@container (min-width: 44rem) {
    .b-cta--gradient-start {
        --cta-gradient-to: transparent;
    }

    /* Rows of 1fr above and below: the words and the buttons stay together in the middle of a
       taller picture instead of spreading over its height. */
    .b-cta--image.b-cta--split .b-cta__inner {
        display: grid;
        grid-template-areas: ". front" "words front" "actions front" ". front";
        grid-template-columns: minmax(0, 1fr) minmax(0, var(--cta-foreground-width, 40%));
        grid-template-rows: 1fr auto auto 1fr;
        align-items: start;
        gap: 0 var(--site-space-7);
    }

    .b-cta--split .b-cta__words {
        grid-area: words;
    }

    .b-cta--split .b-cta__actions {
        grid-area: actions;
        align-self: start;
        margin-top: var(--site-section-actions-space, var(--site-space-5));
    }

    .b-cta--split .b-cta__button {
        flex: 0 0 auto;
    }

    .b-cta--split .b-cta__foreground {
        grid-area: front;
        align-self: center;
        justify-self: center;
    }

    .b-cta--image.b-cta--top-center .b-cta__inner {
        flex-direction: column;
        align-items: center;
        justify-content: flex-start;
    }
}

/* The first button's look (`button_look`), on the theme's tokens: a 1px outline in the colour of
   the words, or the accent darkened by the text colour (the block's `--cta-button-dark`). */
.b-cta .b-cta__button.b-cta__button--outline {
    border-color: currentColor;
    background: transparent;
    color: inherit;
}

.b-cta .b-cta__button.b-cta__button--outline:hover {
    background: color-mix(in srgb, currentColor 12%, transparent);
}

.b-cta .b-cta__button.b-cta__button--primary-dark {
    background: var(--cta-button-dark, color-mix(in srgb, var(--site-color-accent) 70%, var(--site-color-text)));
    color: var(--site-color-accent-contrast);
}

.b-cta .b-cta__button.b-cta__button--primary-dark:hover {
    background: color-mix(in srgb, var(--cta-button-dark, color-mix(in srgb, var(--site-color-accent) 70%, var(--site-color-text))) 85%, var(--site-color-text));
}
